-- Biochemistry Ch1: Amino Acids, Peptides, and Proteins — BATCH 4 (Tertiary & Quaternary Structure, Folding, Denaturation)
-- discipline=biochemistry, foundation=1A. Safe to re-run: deletes only this batch's subtopics.

DELETE FROM questions WHERE topic = 'Amino Acids, Peptides, and Proteins' AND subtopic IN ('Tertiary Structure & Folding', 'Quaternary Structure & Cooperativity', 'Conjugated Proteins & Denaturation');

-- Q1 [Tertiary Structure & Folding] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Tertiary Structure & Folding', 'A globular enzyme is stabilized by several side-chain interactions that hold its single polypeptide in a compact native fold. One of these interactions is the only covalent crosslink contributing to the protein''s tertiary structure. This crosslink is formed by which of the following?', '[{"label": "A", "text": "Oxidation of two cysteine thiols"}, {"label": "B", "text": "Clustering of nonpolar side chains"}, {"label": "C", "text": "Attraction between oppositely charged side chains"}, {"label": "D", "text": "Hydrogen bonding along the backbone"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because a disulfide bond is a covalent \(-\text{S}-\text{S}-\) crosslink formed when two cysteine side-chain thiols are oxidized to give cystine. LibreTexts states that "Two cysteine side chains can covalently interact in a protein to form a disulfide bond (RS-SR), called cystine," with "RSSR ... the oxidized form (S oxidation number -1)" relative to the reduced thiol (line 5892-5894), and that "Disulfide bonds within individual chains and between them stabilize both tertiary and quaternary structures" (line 6613). OpenStax adds that the "Interaction between cysteine side chains forms disulfide linkages in the presence of oxygen, the only covalent bond that forms during protein folding" (line 4437-4438). (Choice A) is correct: it names the oxidation of two cysteine thiols, the reaction that produces the covalent disulfide crosslink. (Choice B) is wrong because clustering of nonpolar side chains is a noncovalent hydrophobic interaction ("induced dipole-induced dipole interactions are often called hydrophobic interactions," line 11101), not a covalent crosslink. (Choice C) is wrong because attraction between oppositely charged side chains is a salt bridge, an "ion-ion" noncovalent interaction (line 11100), not a covalent bond. (Choice D) is wrong because backbone hydrogen bonding defines secondary structure (it produces "regular repeating structures arising when hydrogen bonds between the peptide backbone amide hydrogens and carbonyl oxygens occur," line 6610-6611) and is noncovalent, not the covalent tertiary crosslink described. This is a Knowledge of Scientific Concepts and Principles question because you must recall that disulfide bonds are covalent crosslinks formed by oxidation of cysteine thiols.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
