-- Q2 [Tertiary Structure & Folding] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Tertiary Structure & Folding', 'A globular enzyme folds into its native conformation in the aqueous interior of a cell. The valine and leucine side chains of this folded enzyme are most likely positioned', '[{"label": "A", "text": "on the solvent-exposed outer surface"}, {"label": "B", "text": "buried in the protein''s interior core"}, {"label": "C", "text": "hydrogen-bonded to surrounding water molecules"}, {"label": "D", "text": "forming the peptide bonds of the backbone"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because valine and leucine carry nonpolar, hydrophobic R groups, and when a globular protein folds, the hydrophobic effect drives these nonpolar side chains away from the surrounding water and into the protein''s interior core. LibreTexts states that on folding, "the hydrophobic amino acid side chains are buried in the protein''s interior, surrounded by other hydrophobic side chains," while "the polar and charged side chains [are] on the surface, exposed to water," noting that nonpolar side chains such as Val, Leu, Ile, Met, and Phe are predominantly (83%) in the protein''s interior. OpenStax confirms that "the nonpolar amino acids'' hydrophobic R groups lie in the protein''s interior; whereas, the hydrophilic R groups lie on the outside." (Choice A) is incorrect: the solvent-exposed surface is where polar and charged side chains preferentially sit, not nonpolar Val and Leu, so this reverses the correct relationship. (Choice B) is correct: nonpolar Val and Leu R groups are buried in the hydrophobic interior core, away from water. (Choice C) hydrophobic side chains lack the polar groups needed to hydrogen-bond with water; that behavior describes polar surface residues, not Val and Leu. (Choice D) peptide bonds are formed by the protein backbone between successive alpha-carbons during primary-structure synthesis, not by the valine and leucine R groups, which only participate in higher-order folding interactions. This is a Knowledge of Scientific Concepts and Principles question because you must recall that the hydrophobic effect buries nonpolar side chains in a folded globular protein''s core.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', NULL FROM q
  UNION ALL
