-- Q8 [Tertiary Structure & Folding] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Tertiary Structure & Folding', 'Keratin forms the elongated, insoluble filaments that strengthen hair and nails, whereas myoglobin folds into a compact, water-soluble unit that stores \(\text{O}_2\) in muscle. These two proteins illustrate which structural distinction?', '[{"label": "A", "text": "Keratin is globular; myoglobin is fibrous"}, {"label": "B", "text": "Both proteins are fibrous and insoluble"}, {"label": "C", "text": "Both proteins are globular and soluble"}, {"label": "D", "text": "Keratin is fibrous; myoglobin is globular"}]'::jsonb, 'D', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is D because proteins are classified at the tertiary level by overall 3D shape into two broad architectures: fibrous proteins adopt elongated structures that serve structural roles (e.g., collagen and α-keratin, the major component of hair, skin, and nails), while globular proteins fold into a roughly spherical, compact form (e.g., myoglobin, which binds \(\text{O}_2\)). The textbook notes that large fibrous proteins are not soluble in water, whereas globular proteins are compact with water excluded from their interiors, leaving polar groups on the soluble surface. Keratin''s elongated, insoluble filaments make it fibrous, and myoglobin''s compact, soluble fold makes it globular. (Choice A) reverses the assignment: keratin is the fibrous protein and myoglobin is the globular one, not the opposite. (Choice B) is wrong because myoglobin is not fibrous or insoluble — it is a compact, water-soluble globular protein. (Choice C) is wrong because keratin is not globular or freely soluble — large fibrous proteins such as keratin are insoluble in water. (Choice D) is correct: keratin is an elongated, insoluble fibrous protein, and myoglobin is a compact, soluble globular protein. This is a Knowledge of Scientific Concepts and Principles question because you must recall the distinction between fibrous (elongated, structural, insoluble) and globular (compact, soluble) protein architectures and correctly classify each example.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
