-- Q10 [Tertiary Structure & Folding] medium skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Tertiary Structure & Folding', 'In a folded globular protein, a hydrogen bond forms between the side-chain amide of a glutamine residue and the hydroxyl side chain of a distant threonine residue that lies far away in the linear sequence. This specific side-chain-to-side-chain hydrogen bond most directly stabilizes which level of protein structure?', '[{"label": "A", "text": "Primary structure"}, {"label": "B", "text": "Secondary structure"}, {"label": "C", "text": "Tertiary structure"}, {"label": "D", "text": "Quaternary structure"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because tertiary structure is the overall three-dimensional shape of a single polypeptide, and it is stabilized by interactions between side chains (R-groups) that may be far apart in the linear sequence, including R-group hydrogen bonds, salt bridges, and disulfide bonds. The textbook explicitly classifies a hydrogen bond such as Gln 6 to Thr 107 as "side chain to side chain" (LibreTexts 11145), and defines tertiary structure as "the protein''s overall 3D structure" arising from these embedded side-chain interactions (LibreTexts 11058, 11244). This is distinct from secondary structure, which the same source defines as "the repetitive structure formed from H-bonds among backbone amide H and carbonyl O atoms" (LibreTexts 11243) — a backbone (main-chain) interaction, not a side-chain one. (Choice A) is incorrect: primary structure is only "the linear sequence of the protein" (LibreTexts 11243, 6609) — a covalent peptide-bond sequence, not a hydrogen bond at all. (Choice B) is incorrect: secondary structure (alpha-helix, beta-sheet) is stabilized specifically by hydrogen bonds "among backbone amide H and carbonyl O atoms," i.e., main-chain to main-chain (LibreTexts 11243, 11146); a Gln-to-Thr side-chain hydrogen bond is the wrong interaction type for this level. (Choice C) is correct: a hydrogen bond between two side chains that are distant in the primary sequence is a tertiary-structure interaction, contributing to the overall 3D fold of the single chain (LibreTexts 11058, 11145, 11244). (Choice D) is incorrect: quaternary structure is "the overall structure that arises when separate protein chains aggregate" into multi-subunit assemblies (LibreTexts 11244-11246); it requires more than one polypeptide, whereas the bond described links two residues within a single folded chain. This is a Knowledge of Scientific Concepts and Principles question because you must recall the definitions of each structural level and the distinction between side-chain and backbone hydrogen bonds.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 105)
  RETURNING id
)
