-- Q21 [Conjugated Proteins & Denaturation] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Conjugated Proteins & Denaturation', 'A globular enzyme is incubated in 8 M urea together with beta-mercaptoethanol (a thiol-based reducing agent), and the solution is gently heated until the enzyme loses all catalytic activity. Although every higher-order structural feature has been disrupted, one structural feature of the protein remains intact under these conditions. Which feature is preserved?', '[{"label": "A", "text": "The peptide bonds of the backbone"}, {"label": "B", "text": "The disulfide bonds linking cysteines"}, {"label": "C", "text": "The buried hydrophobic core"}, {"label": "D", "text": "Salt bridges between charged side chains"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because denaturation by urea, heat, and a reducing agent unfolds the protein and destroys its higher-order structure, but it does not cleave the covalent peptide bonds of the backbone. As OpenStax states, a denatured protein loses "its shape without losing its primary sequence," and "the polypeptide''s primary structure is conserved in the process if the denaturing agent is removed." This is exactly why, in Anfinsen''s classic experiment, RNase unfolded by "8 M urea and beta-mercaptoethanol" could recover full activity once the reagents were removed: the amino-acid sequence (the peptide-bonded backbone) survived intact and directed refolding. (Choice A) is correct: the peptide bonds defining the primary structure are the one feature left untouched by these denaturing conditions. (Choice B) is wrong because beta-mercaptoethanol is a reducing agent that specifically cleaves disulfide \(-\text{S}-\text{S}-\) bonds back to free thiols, so the disulfides are broken, not preserved. (Choice C) is wrong because urea and heat disrupt the noncovalent tertiary fold, exposing the previously buried hydrophobic core to solvent; the core is not preserved. (Choice D) is wrong because salt bridges are noncovalent electrostatic R-group interactions that denaturation disrupts along with the rest of the tertiary structure. This is a Scientific Reasoning and Problem Solving question because you must apply the rule that denaturation breaks noncovalent interactions and disulfides while leaving the covalent backbone intact to predict the outcome of a specific multi-reagent treatment.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'partial_truth', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'process_step_confusion', NULL FROM q
  UNION ALL
