-- Q23 [Conjugated Proteins & Denaturation] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Amino Acids, Peptides, and Proteins', 'Conjugated Proteins & Denaturation', 'A globular bacterial enzyme is folded into its active shape by buried hydrophobic side chains and several intrachain disulfide bonds. A researcher heats a purified sample to 90°C for ten minutes; on cooling, the solution turns cloudy and the enzyme shows no catalytic activity, and activity does NOT return. At the molecular level, this heat-killed enzyme most likely retains which feature of the original protein?', '[{"label": "A", "text": "Its buried hydrophobic core"}, {"label": "B", "text": "Its native disulfide bond pattern"}, {"label": "C", "text": "Its peptide-bonded amino acid sequence"}, {"label": "D", "text": "Its catalytically active tertiary fold"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because denaturation by heat destroys the higher-order (tertiary/quaternary) structure and abolishes function, but it does not break the covalent peptide bonds that link the amino acids into the chain. As OpenStax states, when a protein is heated it changes structure, "losing its shape without losing its primary sequence in what scientists call denaturation," and "the polypeptide''s primary structure is conserved in the process." The irreversibility here (cloudiness, no recovery on cooling) mirrors the fried-egg example of irreversible denaturation, yet the underlying linear sequence of peptide-bonded residues is still intact. (Choice A) is incorrect: the hydrophobic effect that buries nonpolar residues in the core is exactly the kind of noncovalent interaction that heat disrupts, so the folded core is lost — "the nonpolar amino acids'' hydrophobic R groups lie in the protein''s interior" only while the protein remains folded. (Choice B) is incorrect: disulfide bonds stabilize the native tertiary fold and are scrambled during denaturation and irreversible aggregation, so the original \(-\text{S}-\text{S}-\) pattern is not preserved — in Anfinsen''s RNase work, refolding after reductive denaturation produced only ~1% activity because the four disulfides reformed randomly. (Choice C) is correct: denaturation eliminates 3D shape and function while "losing its shape without losing its primary sequence," so the peptide-bonded amino acid sequence is the feature that survives. (Choice D) is incorrect: loss of the catalytically active tertiary fold is the definition of denaturation here — "when a protein loses its three-dimensional shape, it may no longer be functional." This is a Scientific Reasoning and Problem Solving question because you must apply the principle that denaturation disrupts noncovalent and disulfide interactions while sparing the covalent backbone to predict which feature of a heat-killed enzyme survives.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 150)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', 'stability-misattribution' FROM q
  UNION ALL
